"""折扣门槛边界样例；输入域与舍入规则见相邻规格。"""


def discounted_total(amount: int) -> int:
    if amount >= 100:
        return amount * 9 // 10
    return amount

first_tests:
from subject import discounted_total

def test_below_threshold():
    assert discounted_total(50) == 50

def test_above_threshold():
    assert discounted_total(150) == 135

